// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 salt) public {
        // Admissible domain: any salt yields a deterministic CREATE2 deployment address.
        Caller caller = new Caller{salt: bytes32(salt)}();
        // The caller is a Bank subclass, so it satisfies c's supportsToken check.
        caller.go(c);
        // Universal rule: after a successful airDrop the caller holds exactly 20 tokens.
        assertTrue(c.tokenBalance(address(caller)) == 20);
    }
}

contract Caller is Bank {
    ModifierEntrancy private c;
    function go(ModifierEntrancy _c) external {
        c = _c;
        c.airDrop();
    }
}
